#include <cstdio>
#include <cstdlib>
#include <new>
struct CDef { long RefCount; };
struct TDefPtr {
    CDef* Object;
    TDefPtr(const TDefPtr& other) : Object(other.Object) { if (Object) ++Object->RefCount; }
};
